"""Atomic full-state CPM checkpoints; load only files generated by this project.

The format marker prevents accidental replacement of unrelated artifacts. It is
not a security signature: torch.load(weights_only=False) still requires a trusted
checkpoint. RNG restoration is explicit, after the trainer skips consumed batches.
"""

from __future__ import annotations

import copy
import json
import math
import os
from pathlib import Path
import random
import tempfile
from typing import Any
import zipfile

import numpy as np
import torch

CHECKPOINT_FORMAT = "openpi_touchguide_cpm_train_v1"
_MARKER_NAME = "touchguide_checkpoint_format"
_PAYLOAD_KEYS = {
    "format",
    "progress",
    "contract",
    "run",
    "rng_state",
    "model_state",
    "optimizer_state",
    "scheduler_state",
}


def _validate_progress(progress: dict[str, Any]) -> None:
    if not isinstance(progress, dict):
        raise ValueError("Checkpoint progress must be a dictionary")
    for key in ("epoch", "batch_in_epoch", "global_step"):
        value = progress.get(key)
        if not isinstance(value, int) or isinstance(value, bool) or value < 0:
            raise ValueError(f"Progress {key} must be a nonnegative integer")
    if "best_val" not in progress:
        raise ValueError("Progress must include best_val")
    best_val = progress["best_val"]
    if best_val is not None and (
        not isinstance(best_val, (int, float))
        or isinstance(best_val, bool)
        or math.isnan(best_val)
        or best_val == -math.inf
    ):
        raise ValueError("best_val must be a finite number, positive infinity, or None")


def _contract_json(contract: dict[str, Any]) -> str:
    if not isinstance(contract, dict) or not contract:
        raise ValueError("Checkpoint contract must be a nonempty JSON dictionary")

    def validate_keys(value: Any) -> None:
        if isinstance(value, dict):
            if any(not isinstance(key, str) for key in value):
                raise ValueError("Contract dictionary keys must be strings")
            for child in value.values():
                validate_keys(child)
        elif isinstance(value, list):
            for child in value:
                validate_keys(child)
        elif value is not None and not isinstance(value, (str, bool, int, float)):
            raise ValueError("Contract values must be JSON primitives, lists, or dictionaries")

    validate_keys(contract)
    try:
        return json.dumps(contract, sort_keys=True, separators=(",", ":"), allow_nan=False)
    except (TypeError, ValueError) as error:
        raise ValueError("Checkpoint contract must contain finite JSON values") from error


def capture_rng_state() -> dict[str, Any]:
    """Capture global RNGs, including all CUDA generators when CUDA is initialized."""
    numpy_state = np.random.get_state()
    return {
        "python": random.getstate(),
        "numpy": (numpy_state[0], numpy_state[1].copy(), *numpy_state[2:]),
        "torch_cpu": torch.get_rng_state().clone(),
        "torch_cuda": [state.clone() for state in torch.cuda.get_rng_state_all()]
        if torch.cuda.is_initialized()
        else [],
    }


def _validate_rng_state(state: dict[str, Any]) -> None:
    if not isinstance(state, dict) or set(state) != {"python", "numpy", "torch_cpu", "torch_cuda"}:
        raise ValueError("Invalid checkpoint RNG state keys")
    try:
        random.Random().setstate(state["python"])
        np.random.RandomState().set_state(state["numpy"])
        torch.Generator(device="cpu").set_state(state["torch_cpu"])
    except (TypeError, ValueError, RuntimeError) as error:
        raise ValueError("Invalid checkpoint CPU RNG state") from error
    cuda_state = state["torch_cuda"]
    if not isinstance(cuda_state, list) or any(
        not isinstance(value, torch.Tensor) or value.dtype != torch.uint8 or value.ndim != 1 for value in cuda_state
    ):
        raise ValueError("Invalid checkpoint CUDA RNG states")


def restore_rng_state(state: dict[str, Any]) -> None:
    """Explicitly restore global RNGs; this does not restore workers or sampler state.

    The synchronous trainer must first reconstruct its epoch loader and consume the
    saved batch prefix. GPU resume is not promised to be bitwise reproducible.
    """
    _validate_rng_state(state)
    cuda_state = state["torch_cuda"]
    if cuda_state and (not torch.cuda.is_available() or len(cuda_state) > torch.cuda.device_count()):
        raise RuntimeError("Restoring saved CUDA RNGs requires at least the saved number of visible CUDA devices")
    random.setstate(state["python"])
    np.random.set_state(state["numpy"])
    torch.set_rng_state(state["torch_cpu"].cpu())
    if cuda_state:
        torch.cuda.set_rng_state_all([value.cpu() for value in cuda_state])


def _marker_matches(path: Path) -> bool:
    try:
        with zipfile.ZipFile(path) as archive:
            markers = [name for name in archive.namelist() if name.endswith(f"/{_MARKER_NAME}")]
            return (
                len(markers) == 1
                and archive.getinfo(markers[0]).file_size < 128
                and archive.read(markers[0]) == CHECKPOINT_FORMAT.encode("utf-8")
            )
    except (OSError, zipfile.BadZipFile, RuntimeError):
        return False


def _guard_destination(path: Path) -> None:
    if path.is_symlink():
        raise ValueError("Checkpoint destination must not be a symbolic link")
    if path.exists() and (not path.is_file() or not _marker_matches(path)):
        raise ValueError("Refusing to overwrite an unrelated artifact or another checkpoint format")


def _add_format_marker(path: Path) -> None:
    with zipfile.ZipFile(path, "a") as archive:
        records = [name for name in archive.namelist() if name.endswith("/data.pkl")]
        if len(records) != 1:
            raise ValueError("Expected a standard torch.save ZIP checkpoint")
        prefix = records[0].rsplit("/", 1)[0]
        archive.writestr(f"{prefix}/{_MARKER_NAME}", CHECKPOINT_FORMAT)


def save_checkpoint(
    path: str | Path,
    *,
    model: torch.nn.Module,
    optimizer: torch.optim.Optimizer,
    scheduler: Any,
    progress: dict[str, Any],
    contract: dict[str, Any],
    run: dict[str, Any] | None = None,
    rng_state: dict[str, Any] | None = None,
) -> None:
    """Save full model/Adam/scheduler state, progress, strict contract and run metadata.

    ``epoch`` is zero-based; ``batch_in_epoch`` counts already consumed batches.
    The caller supplies its config digest and total_epochs in contract, and W&B
    id/name/entity/project in run. A path may replace only this checkpoint format.
    """
    _validate_progress(progress)
    _contract_json(contract)
    if run is not None and not isinstance(run, dict):
        raise ValueError("Checkpoint run metadata must be a dictionary or None")
    if rng_state is not None:
        _validate_rng_state(rng_state)
    destination = Path(path).expanduser()
    _guard_destination(destination)
    destination.parent.mkdir(parents=True, exist_ok=True)
    payload = {
        "format": CHECKPOINT_FORMAT,
        "progress": copy.deepcopy(progress),
        "contract": copy.deepcopy(contract),
        "run": copy.deepcopy(run),
        "rng_state": capture_rng_state() if rng_state is None else copy.deepcopy(rng_state),
        # Include frozen DINOv2 as well as trainable heads; no prefix filtering.
        "model_state": model.state_dict(),
        "optimizer_state": optimizer.state_dict(),
        "scheduler_state": scheduler.state_dict(),
    }
    descriptor, temporary_name = tempfile.mkstemp(prefix=f".{destination.name}.", suffix=".tmp", dir=destination.parent)
    temporary = Path(temporary_name)
    try:
        with os.fdopen(descriptor, "wb") as stream:
            torch.save(payload, stream)
        _add_format_marker(temporary)
        with temporary.open("rb") as stream:
            os.fsync(stream.fileno())
        _guard_destination(destination)
        os.replace(temporary, destination)
        directory_descriptor = os.open(destination.parent, os.O_RDONLY | os.O_DIRECTORY)
        try:
            os.fsync(directory_descriptor)
        finally:
            os.close(directory_descriptor)
    finally:
        temporary.unlink(missing_ok=True)


def load_checkpoint(
    path: str | Path,
    *,
    model: torch.nn.Module,
    optimizer: torch.optim.Optimizer,
    scheduler: Any,
    expected_contract: dict[str, Any],
) -> dict[str, Any]:
    """Load a trusted self-generated checkpoint without restoring its RNG yet.

    Construct optimizer and scheduler before calling this function. Loading the
    optimizer through PyTorch recursively places tensor state with its parameters,
    while respecting optimizer-specific handling of Adam's step (CPU unless fused
    or capturable). Do not blindly move every state tensor to CUDA afterward.
    """
    expected_json = _contract_json(expected_contract)
    source = Path(path).expanduser()
    if source.is_symlink() or not source.is_file() or not _marker_matches(source):
        raise ValueError("Expected a trusted checkpoint in the CPM training format")
    payload = torch.load(source, map_location="cpu", weights_only=False)
    if not isinstance(payload, dict) or set(payload) != _PAYLOAD_KEYS or payload["format"] != CHECKPOINT_FORMAT:
        raise ValueError("Invalid CPM checkpoint format or payload keys")
    _validate_progress(payload["progress"])
    if _contract_json(payload["contract"]) != expected_json:
        raise ValueError("Checkpoint contract does not match the current training contract")
    if payload["run"] is not None and not isinstance(payload["run"], dict):
        raise ValueError("Invalid checkpoint run metadata")
    _validate_rng_state(payload["rng_state"])
    for key in ("model_state", "optimizer_state", "scheduler_state"):
        if not isinstance(payload[key], dict):
            raise ValueError(f"Invalid checkpoint {key}")
    current_state = model.state_dict()
    if set(current_state) != set(payload["model_state"]):
        raise ValueError("Checkpoint model state keys do not match the current model")
    for key, value in current_state.items():
        saved = payload["model_state"][key]
        if isinstance(value, torch.Tensor) and (not isinstance(saved, torch.Tensor) or value.shape != saved.shape):
            raise ValueError(f"Checkpoint model state shape mismatch: {key}")
    model.load_state_dict(payload["model_state"], strict=True)
    optimizer.load_state_dict(payload["optimizer_state"])
    scheduler.load_state_dict(payload["scheduler_state"])
    return payload
